import subprocess

def get_disk_usage(directory):
    try:
        output = subprocess.check_output(['du', '-sh', directory]).decode('utf-8')
        return output.strip()
    except subprocess.CalledProcessError as e:
        if e.returncode == 13:  # PermissionError
            return f"Permission denied: {directory}"
        elif e.returncode == 2:  # No such file or directory
            return f"Directory not found: {directory}"
        else:
            raise
