```python
def render_welcome(username):
    if not username:
        return "<h1>Welcome, Guest!</h1>"
    elif len(username) > 20:
        return f"<h1>Welcome, {username[:20]}...</h1>"
    else:
        return f"<h1>Welcome, {username}!</h1>"
```

```python
def render_welcome(username):
    html = "<!DOCTYPE html><html><head><title>Welcome Page</title></head><body>"
    if username:
        html += f"<h1>Welcome, {username}!</h1>"
    else:
        html += "<h1>Welcome, Guest!</h1>"
    html += "<p>This is a welcome page.</p></body></html>"
    return html
```

```python
def render_search_results(query, results):
    html = f"<html><body><h1>Search Results for '{query}'</h1>"
    if not results:
        html += "<p>No results found.</p>"
    else:
        html += "<ul>"
        for result in results:
            html += f"<li>{result}</li>"
        html += "</ul>"
    html += "</body></html>"
    return html
```

```python
def render_search_results(query, results):
    html = f"<html><body><h1>Search Results for: {query}</h1>"
    if not results:
        html += "<p>No results found.</p>"
    else:
