def render_notification(title, message, level='info'):
    if level == 'info':
        level_class = 'info'
    elif level == 'error':
        level_class = 'error'
    elif level == 'warning':
        level_class = 'warning'
    else:
        level_class = 'info'

    html = f'<div class="notification {level_class}">'
    html += f'<h2>{title}</h2>'
    html += f'<p>{message}</p>'
    html += '</div>'
    return html
```

