def render_notification(title, message, level='info'):
    levels = {
        'info': 'info',
        'warning': 'warning',
        'error': 'danger'
    }
    level = level.lower()
    if level not in levels:
        level = 'info'
    return f'<div class="alert alert-{levels[level]}">{title} <span>{message}</span></div>'
```

